package com.cricketprediction.backend.model;

import jakarta.persistence.*;
import lombok.*;

import java.time.LocalDateTime;

/**
 * A single prediction generated by the ML service and stored for audit and display.
 *
 * The prediction is intentionally minimal — it stores what the ML service returned,
 * not any derived or speculative values.
 */
@Entity
@Table(name = "predictions")
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class Prediction {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** Player name (human-readable, as used in the ML dataset). */
    @Column(nullable = false)
    private String playerName;

    /** Venue name as sent to the ML service (optional). */
    @Column(nullable = true)
    private String venue;

    /** Opposing team name as sent to the ML service. */
    @Column(nullable = false)
    private String opponent;

    /** Canonical match type: t20i | odi | test */
    @Column(nullable = false)
    private String matchType;

    /** Predicted run total returned by the ML model (runs ≥ 0). */
    @Column(nullable = false)
    private Double predictedRuns;

    /** Timestamp when this prediction was generated. */
    @Column(nullable = false)
    private LocalDateTime predictionDate;

    /**
     * Identifier of the model that generated this prediction.
     * E.g. "SVR" (best_regression_model.pkl class name).
     */
    private String modelName;

    /**
     * Predicted performance tier from classification model.
     * E.g. "Poor", "Average", "Good", "Excellent".
     */
    private String predictedTier;

    /**
     * Identifier of the classifier model.
     * E.g. "MLPClassifier".
     */
    private String classifierName;

    /** Optional: the user who requested this prediction. */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private User requestedBy;
}
